from datetime import date, timedelta

class Loyalty:
    def __init__(self) -> None:
        self.customers = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        """Record a purchase; returns the number of points earned."""
        if amount <= 0:
            raise ValueError("Purchase amount must be greater than zero")

        points = int(amount // 10)
        if customer not in self.customers:
            self.customers[customer] = {'purchases': [], 'balance': 0}
        self.customers[customer]['purchases'].append((points, day))
        return points

    def balance(self, customer: str, day: date) -> int:
        """Points the customer can spend on the given day."""
        if customer not in self.customers:
            return 0
        available_points = 0
        for points, purchase_day in self.customers[customer]['purchases']:
            if (day - purchase_day).days >= 14:
                available_points += points
        self.customers[customer]['balance'] = available_points
        return available_points

    def redeem(self, customer: str, points: int, day: date) -> None:
        """Redeem points."""
        if points % 100 != 0:
            raise ValueError("Points can only be redeemed in multiples of 100")
        if customer not in self.customers:
            raise ValueError("Customer has no balance")
        available_points = self.balance(customer, day)
        if points > available_points:
            raise ValueError("Insufficient points to redeem")
        self.customers[customer]['balance'] -= points

# Example usage:
loyalty = Loyalty()
loyalty.purchase('John Doe', 100.0, date(2024, 1, 1))
print(loyalty.balance('John Doe', date(2024, 1, 14)))  # Output: 10
loyalty.redeem('John Doe', 100, date(2024, 1, 14))
print(loyalty.balance('John Doe', date(2024, 1, 14)))  # Output: 0
```

